"""Refresh the ontology-review HTTP test fixture.

`src-tauri/tests/ontology_web_http.rs` used to assert hardcoded counts
(`77 concepts`, `11 P0`) against `reports/ontology_review/workstation/`, which is
**gitignored**: it is regenerated by `python -m ml.gpo_ontology_review build`
against whatever data the operator happens to have collected. The test therefore
passed or failed with the local dataset rather than with the code, and on a fresh
clone it failed outright because the directory does not exist at all.

The fix is to commit a snapshot of that generated index under
`src-tauri/tests/fixtures/ontology_review/` and read every expected value from it,
so the suite is hermetic. Refreshing the fixture is then a deliberate act:

    python scripts/gen_ontology_review_fixture.py

The fixture records its own provenance and SHA-256s in `fixture_manifest.json`,
and the test asserts them, so a snapshot cannot be swapped for a weaker one
without the diff showing it.

READ-ONLY over the real report directory and the dataset; writes only inside the
fixture directory.
"""

from __future__ import annotations

import hashlib
import json
import os
import shutil
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[1]
REAL = REPO_ROOT / "reports" / "ontology_review"
FIXTURE = REPO_ROOT / "src-tauri" / "tests" / "fixtures" / "ontology_review"

#: Copied verbatim: the index, the KB reference and the structural signals.
COPIED = ["index.json", "kb_entities.json", "structural.json"]


def sha256(p: Path) -> str:
    return hashlib.sha256(p.read_bytes()).hexdigest()


def main() -> int:
    ws = REAL / "workstation"
    if not (ws / "index.json").is_file():
        raise SystemExit(
            f"no generated index at {ws}. Build it first:\n"
            f"    python -m ml.gpo_ontology_review build"
        )
    if FIXTURE.exists():
        shutil.rmtree(FIXTURE)
    (FIXTURE / "report" / "workstation" / "thumbs").mkdir(parents=True)
    (FIXTURE / "dataset" / "images").mkdir(parents=True)

    copied: dict[str, str] = {}
    for name in COPIED:
        src = ws / name
        dst = FIXTURE / "report" / "workstation" / name
        shutil.copy2(src, dst)
        copied[f"report/workstation/{name}"] = sha256(dst)

    # The queue is the index's own concept order, so the first pending concept and
    # its first evidence image are deterministic - and exactly what the test
    # fetches. Both transports are captured so the test never needs the live
    # dataset: the thumbnail through the sandbox, the full-resolution PNG through
    # GPO_DATASET_ROOT.
    index = json.loads((ws / "index.json").read_text(encoding="utf-8"))
    concepts = index.get("concepts") or []
    if not concepts:
        raise SystemExit("index has no concepts; refusing to record an empty fixture")
    first = concepts[0]
    evidence = first.get("evidence") or []
    if not evidence:
        raise SystemExit(f"first concept {first.get('conceptId')} has no evidence image")
    image_id = evidence[0]["imageId"]

    thumb_src = ws / "thumbs" / f"{image_id}.jpg"
    shutil.copy2(thumb_src, FIXTURE / "report" / "workstation" / "thumbs" / f"{image_id}.jpg")
    copied[f"report/workstation/thumbs/{image_id}.jpg"] = sha256(
        FIXTURE / "report" / "workstation" / "thumbs" / f"{image_id}.jpg"
    )

    appdata = Path(os.environ.get("APPDATA", "")) / "gpo-autofish"
    full_src = appdata / "datasets" / "gpo-vision" / "v1" / "images" / f"{image_id}.png"
    if not full_src.is_file():
        raise SystemExit(f"missing full-resolution image {full_src}; the fixture would 404")
    shutil.copy2(full_src, FIXTURE / "dataset" / "images" / f"{image_id}.png")
    copied[f"dataset/images/{image_id}.png"] = sha256(
        FIXTURE / "dataset" / "images" / f"{image_id}.png"
    )

    wiki_src = REAL / "wiki_fish.json"
    shutil.copy2(wiki_src, FIXTURE / "report" / "wiki_fish.json")
    copied["report/wiki_fish.json"] = sha256(FIXTURE / "report" / "wiki_fish.json")

    p0 = sum(1 for c in concepts if c.get("priority") == "P0")
    bands: dict[str, int] = {}
    for c in concepts:
        bands[c.get("priority", "P3")] = bands.get(c.get("priority", "P3"), 0) + 1

    manifest = {
        "kind": "ontology-review-http-fixture",
        "version": 1,
        "source": {
            "index": str((REAL / "workstation" / "index.json").relative_to(REPO_ROOT)),
            "index_sha256": sha256(REAL / "workstation" / "index.json"),
            "labels_sha256": sha256(
                appdata / "datasets" / "gpo-vision" / "v1" / "labels.jsonl"
            ),
            "reviews_sha256": sha256(appdata / "reviews.jsonl"),
            "note": (
                "snapshot of the generated workstation index; refresh with "
                "`python scripts/gen_ontology_review_fixture.py`"
            ),
        },
        "concepts": len(concepts),
        "p0": p0,
        "bands": dict(sorted(bands.items())),
        "first_concept": first["conceptId"],
        "first_evidence_image": image_id,
        "wiki_fish_entries": len(
            json.loads((FIXTURE / "report" / "wiki_fish.json").read_text(encoding="utf-8"))["entries"]
        ),
        "files": dict(sorted(copied.items())),
    }
    (FIXTURE / "fixture_manifest.json").write_text(
        json.dumps(manifest, indent=1, sort_keys=True) + "\n", encoding="utf-8"
    )

    (FIXTURE / "README.md").write_text(
        "# Ontology review HTTP fixture\n"
        "\n"
        "A snapshot of `reports/ontology_review/workstation/` (which is gitignored and\n"
        "regenerated from live data) plus the one evidence image the HTTP test fetches\n"
        "both ways: the JPEG thumbnail from the sandbox, the full-resolution PNG through\n"
        "`GPO_DATASET_ROOT`.\n"
        "\n"
        "It exists so `tests/ontology_web_http.rs` is hermetic: the reviewer-facing\n"
        "numbers are asserted against THIS file, and cross-checked against the server's\n"
        "own `counts`, so the contract is 'the API reports exactly the index it serves',\n"
        "not a magic constant that breaks whenever the operator collects a fish.\n"
        "\n"
        f"Recorded state: {len(concepts)} concepts, {p0} at P0, bands {manifest['bands']}.\n"
        "Those numbers are pinned in `fixture_manifest.json` together with every file's\n"
        "SHA-256, so replacing this fixture is a visible, deliberate act.\n"
        "\n"
        "Refresh: `python scripts/gen_ontology_review_fixture.py`\n",
        encoding="utf-8",
    )
    print(f"wrote {FIXTURE}")
    print(f"  concepts={len(concepts)} p0={p0} bands={manifest['bands']}")
    print(f"  first concept={first['conceptId']} image={image_id}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())